export const symbols=['BTC-USD','ETH-USD','SOL-USD'],sources=['atlas','beacon','cobalt'];
export function normalize(source,r){if(!sources.includes(source)||!r||typeof r!=='object')throw Error('Invalid source record');let id,symbol,price,size,timestamp;
if(r.source===source&&r.symbol){({id,symbol,price,size,timestamp}=r);}else if(source==='atlas'){({id,symbol,price,size,timestamp}=r);}else if(source==='beacon'){id=r.trade_id;symbol=r.pair?.replace('/','-');price=r.p;size=r.q;timestamp=typeof r.ts==='number'?r.ts*1000:NaN;}else{id=r.seq;symbol=r.instrument?.replace('_','-');price=r.last;size=r.amount;timestamp=r.time_ms;}
if(!['string','number'].includes(typeof id)||!String(id).trim()||typeof symbol!=='string')throw Error('Invalid ID or symbol');symbol=symbol.toUpperCase();if(!symbols.includes(symbol))throw Error('Unsupported symbol');const numeric=[price,size,timestamp].map(v=>{if(!['string','number'].includes(typeof v)||String(v).trim()===''||!Number.isFinite(Number(v))||Number(v)<=0)throw Error('Price, size and time must be positive finite numbers');return Number(v);});[price,size,timestamp]=numeric;if(timestamp>8640000000000000)throw Error('Timestamp out of range');return {source,id:String(id),symbol,price,size,timestamp};}
export class Engine{constructor(){this.records=[];this.seen=new Set();this.keys=[];this.latest=new Map();this.stats={accepted:0,rejected:0,duplicates:0,out_of_order:0};this.issues=[];this.processing=[];}
ingest(source,raw){const start=performance.now();let tick;try{tick=normalize(source,raw);}catch(e){this.stats.rejected++;this.issues.unshift({source,error:e.message});this.issues=this.issues.slice(0,50);return null;}const id=JSON.stringify([source,tick.id]);if(this.seen.has(id)){this.stats.duplicates++;return null;}this.seen.add(id);this.keys.push(id);if(this.keys.length>10000)this.seen.delete(this.keys.shift());const key=source+tick.symbol;const previous=this.latest.get(key);if(previous&&tick.timestamp<previous.timestamp)this.stats.out_of_order++;else this.latest.set(key,tick);this.stats.accepted++;this.records.push(tick);if(this.records.length>2000)this.records.shift();this.processing.push(performance.now()-start);if(this.processing.length>2000)this.processing.shift();return tick;}
quote(symbol){return [...this.latest.values()].filter(t=>t.symbol===symbol).sort((a,b)=>b.timestamp-a.timestamp)[0]||null;}}
export function createGenerator(seed=7){let seq=0,state=seed;const random=()=>{state=(state*16807)%2147483647;return state/2147483647;};return source=>{const symbol=symbols[seq%3],price=[64000,3200,150][seq%3]*(1+(random()-.5)*.006),size=+(random()*2+.01).toFixed(3),timestamp=Date.now(),id=`demo-${seed}-${seq++}`;if(source==='atlas')return {id,symbol,price,size,timestamp};if(source==='beacon')return {trade_id:id,pair:symbol.replace('-','/'),p:price.toFixed(4),q:String(size),ts:timestamp/1000};return {seq:id,instrument:symbol.replace('-','_'),last:price,amount:size,time_ms:timestamp};};}
